insert into public.courses (id, slug, name, category, emoji, accent_color, short_description, description, number_reason, outcomes, notice, days, price_cents, currency, grace_days, status, sort_order, faq) values
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 'fix-your-money', 'Fix Your Money', 'Money', '💰', '#2F7D57', '31 small money moves. See where it goes, take control, start growing it.', 'Most money advice fails because it asks you to change everything at once. This course gives you one small money action a day for a full month, so every bill, subscription and payday passes through your hands once. By the end you know your numbers, you''ve plugged your leaks and you have a simple system that runs without willpower.', 'One full money cycle — every bill, subscription and payday shows up once', '["Know exactly where your money went this month","Cancel the spending you don''t actually value","Set up automatic saving that happens before you can spend","A simple plan for debt, an emergency fund and your first investments"]'::jsonb, null, 31, 999, 'usd', 0, 'published', 1, '[{"q":"How much time does each day take?","a":"Most tasks take 5–15 minutes. Each day you do one small action and answer one question about it."},{"q":"What if I miss a day?","a":"Each day''s task is only open that day, in your timezone. A missed day can''t be redone, and the refund guarantee needs you to respond on every day (minus any grace days shown on this page). You can still finish the course."},{"q":"Do I need to read the books first?","a":"No. Each task gives you the one idea you need, in plain language. If a book grabs you, read it alongside."},{"q":"Is this financial advice?","a":"No. It''s general education and daily practice. For decisions about your own situation, talk to a licensed professional."}]'::jsonb),
  ('33721a9a-e30c-5b65-aa47-b904fe2bfd83', 'build-discipline', 'Build Discipline', 'Habits', '🔥', '#B04A26', '66 days to make one habit automatic — and prove you can keep a promise to yourself.', 'Discipline isn''t a personality trait. It''s what''s left after you make the right thing easy and repeat it until it stops needing effort. Over 66 days you''ll pick one keystone habit, shrink it until it''s impossible to skip, and build the evidence — one day at a time — that you are someone who shows up.', 'The real time it takes to build a habit (UCL study, Lally et al. 2009: 66 days on average)', '["One habit that runs on autopilot","A system for starting when you don''t feel like it","66 written entries proving you kept your word","The tools to build your next habit without a course"]'::jsonb, null, 66, 1299, 'usd', 0, 'published', 2, '[{"q":"How much time does each day take?","a":"Most tasks take 5–15 minutes. Each day you do one small action and answer one question about it."},{"q":"What if I miss a day?","a":"Each day''s task is only open that day, in your timezone. A missed day can''t be redone, and the refund guarantee needs you to respond on every day (minus any grace days shown on this page). You can still finish the course."},{"q":"Do I need to read the books first?","a":"No. Each task gives you the one idea you need, in plain language. If a book grabs you, read it alongside."},{"q":"66 days is long. What if I fall off?","a":"That''s exactly what the course trains. The daily response is the habit. Showing up for two minutes on a bad day counts."}]'::jsonb),
  ('b9e48da4-691f-5012-ad0c-6f435d1e7990', 'ai-for-everyday-life', 'AI for Everyday Life', 'AI', '🤖', '#2F5FB3', '21 practical AI skills in 21 days — for work, for learning and for making things.', 'You don''t need to understand how AI works to get real value from it. You need practice. Each day you''ll try one concrete use — on your own work, your own questions, your own projects — and write down what happened. Three weeks later you''ll know what AI is good at, where it fails, and how to use it without handing over your judgment.', '3 weeks, 21 skills — Work → Learning → Creating', '["Use AI confidently for writing, planning and research","Learn anything faster with AI as a patient tutor","Know when not to trust the answer","A personal list of prompts that actually work for you"]'::jsonb, null, 21, 799, 'usd', 0, 'published', 3, '[{"q":"How much time does each day take?","a":"Most tasks take 5–15 minutes. Each day you do one small action and answer one question about it."},{"q":"What if I miss a day?","a":"Each day''s task is only open that day, in your timezone. A missed day can''t be redone, and the refund guarantee needs you to respond on every day (minus any grace days shown on this page). You can still finish the course."},{"q":"Do I need to read the books first?","a":"No. Each task gives you the one idea you need, in plain language. If a book grabs you, read it alongside."},{"q":"Which AI tool do I need?","a":"Any free chat assistant works — ChatGPT, Claude, Gemini or Copilot. No paid plan is needed."}]'::jsonb),
  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 'get-fit-stay-healthy', 'Get Fit, Stay Healthy', 'Health', '🏃', '#177272', '42 days of walking, sleep, mobility and bodyweight basics. No gym, no extremes.', 'Health isn''t built in a brutal month — it''s built from boring basics done most days. For six weeks you''ll do one small thing daily: move a little, sleep a little better, get a little stronger. Nothing here needs equipment or a gym. It''s the foundation that everything else sits on.', '6 weeks to feel the change', '["A daily walking habit you actually keep","A calmer evening routine and more consistent sleep","Basic strength and mobility you can do at home","Energy you can feel by the end of week six"]'::jsonb, 'Not medical advice — check with a doctor before starting new exercise.', 42, 999, 'usd', 0, 'published', 4, '[{"q":"How much time does each day take?","a":"Most tasks take 5–15 minutes. Each day you do one small action and answer one question about it."},{"q":"What if I miss a day?","a":"Each day''s task is only open that day, in your timezone. A missed day can''t be redone, and the refund guarantee needs you to respond on every day (minus any grace days shown on this page). You can still finish the course."},{"q":"Do I need to read the books first?","a":"No. Each task gives you the one idea you need, in plain language. If a book grabs you, read it alongside."},{"q":"Do I need a gym or equipment?","a":"No. Everything is walking, sleep, mobility and bodyweight basics you can do at home."},{"q":"Is this medical advice?","a":"No. It''s general wellness education. Check with a doctor before starting new exercise, especially if you have a health condition."}]'::jsonb),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 'stop-procrastinating', 'Stop Procrastinating', 'Productivity', '⏳', '#7A4FB5', '24 days to see your time clearly, take control of it and protect your focus.', 'Procrastination isn''t laziness — it''s avoiding a feeling. This course gives you one small action a day to face the thing you''re avoiding, choose what actually matters and build blocks of real focus. Twenty-four days, one for every hour you have.', 'One day for every hour you have', '["Start your hardest task first, without the dread","A weekly plan built around what matters most","Daily blocks of distraction-free focus","Peace with the fact that you can''t do everything"]'::jsonb, null, 24, 799, 'usd', 0, 'published', 5, '[{"q":"How much time does each day take?","a":"Most tasks take 5–15 minutes. Each day you do one small action and answer one question about it."},{"q":"What if I miss a day?","a":"Each day''s task is only open that day, in your timezone. A missed day can''t be redone, and the refund guarantee needs you to respond on every day (minus any grace days shown on this page). You can still finish the course."},{"q":"Do I need to read the books first?","a":"No. Each task gives you the one idea you need, in plain language. If a book grabs you, read it alongside."}]'::jsonb),
  ('0cf63e3a-f5f9-5b2f-aa36-0874ae4318cd', 'talk-with-confidence', 'Talk with Confidence', 'Communication', '🗣️', '#8F5A0E', '33 people-skills, one a day. Be liked, be heard and hold your ground kindly.', 'Good communicators aren''t born charming — they practise a small set of principles until they''re natural. Each day you''ll try one in a real conversation: at work, at home, with a stranger. Thirty-three days later, talking to people feels less like a risk and more like a skill.', '33 principles, one a day (30 from How to Win Friends + 3 negotiation tactics)', '["Start conversations without overthinking","Make people feel heard — and get heard in return","Disagree and give feedback without a fight","Negotiate calmly using simple, ethical tactics"]'::jsonb, null, 33, 999, 'usd', 0, 'published', 6, '[{"q":"How much time does each day take?","a":"Most tasks take 5–15 minutes. Each day you do one small action and answer one question about it."},{"q":"What if I miss a day?","a":"Each day''s task is only open that day, in your timezone. A missed day can''t be redone, and the refund guarantee needs you to respond on every day (minus any grace days shown on this page). You can still finish the course."},{"q":"Do I need to read the books first?","a":"No. Each task gives you the one idea you need, in plain language. If a book grabs you, read it alongside."},{"q":"Is this about manipulating people?","a":"No. We only use principles that work when the other person knows exactly what you''re doing: listening, honesty, respect."}]'::jsonb)
