insert into public.tasks (course_id, day_number, title, book_insight, book_reference, instructions, response_prompt, min_response_chars, is_sample) values
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 1, 'Write down your real number', 'How we handle money has less to do with what we know and more to do with how we behave — and behaviour starts with seeing clearly. Most people carry a vague feeling about their finances instead of an actual number. A feeling can''t be improved; a number can.', 'The Psychology of Money — Morgan Housel', '["Open every account you have: chequing, savings, credit cards, loans.","Add up what you own in cash and savings. Add up what you owe.","Subtract what you owe from what you own. That is today''s number.","Don''t judge it. Today is only about looking."]'::jsonb, 'What did it feel like to see your real number? What surprised you most? (You don''t have to share the number itself.)', 0, true),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 2, 'Track every dollar for one day', 'A conscious spending plan begins with knowing what you spend now, not what you imagine you spend. Small, automatic purchases are the ones we forget, and they add up quietly. One honest day of tracking shows you more than a month of guessing.', 'I Will Teach You to Be Rich — Ramit Sethi', '["From the moment you read this, write down every purchase today — even a coffee.","Use your phone notes. Amount and what it was. Nothing else.","Tonight, mark each one: needed it, loved it, or didn''t notice it."]'::jsonb, 'What did you spend money on today, and which purchase would you not miss if it disappeared?', 0, true),
  ('3dd35700-943e-5264-ad06-a44982ca9cc3', 3, 'Pay yourself first — even $5', 'One of the oldest money rules is to keep a part of everything you earn before you spend the rest. The amount matters less than the order: saving first makes it a habit, saving what''s left makes it an accident. Wealth is mostly what you don''t spend.', 'The Richest Man in Babylon — George S. Clason', '["Pick an amount you will not miss. $5 is enough to start.","Move it into a savings account right now.","If your bank allows it, set this up as an automatic transfer on payday."]'::jsonb, 'How much did you move, and what will you set as your automatic ''pay yourself first'' amount?', 0, true),
