  ('ee91d74f-807f-5be5-a70a-95e266c4bbc9', 42, 'Day 42 — coming soon', '', '', '[]'::jsonb, 'What did you do today, and what did you notice?', 0, false),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 1, 'Name your frog', 'The task you''re most likely to put off is usually the one that would make the biggest difference. If you do that one first, the rest of the day gets lighter. Naming it clearly is half the battle — vague tasks are easy to avoid.', 'Eat That Frog! — Brian Tracy', '["Write down the one task you''ve been avoiding the longest.","Write the very first physical step (open the file, find the number, write one line).","Do only that first step today. Stop there if you want."]'::jsonb, 'What is your frog, and what happened when you did the first step?', 0, true),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 2, 'Count your weeks', 'A human life is short — roughly four thousand weeks. You will never get everything done, and accepting that is freeing: it lets you choose a few things that matter instead of drowning in all of them. Time management starts with admitting the limit.', 'Four Thousand Weeks — Oliver Burkeman', '["Multiply your age by 52. Subtract it from 4,000.","Look at the number for a minute.","Write down three things you''d regret never starting.","Circle the one you would start this week."]'::jsonb, 'What did you circle, and what have you been doing instead of it?', 0, true),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 3, 'Sort urgent from important', 'Urgent things shout; important things wait quietly. Most of what moves a life forward is important but not urgent, so it gets pushed aside by whatever is loudest. Putting first things first means scheduling the quiet ones on purpose.', 'The 7 Habits of Highly Effective People — Stephen R. Covey', '["List everything on your plate today.","Mark each item: urgent, important, both or neither.","Choose one item that is important but NOT urgent.","Give it 20 minutes today, before the urgent things."]'::jsonb, 'Which important-but-not-urgent thing did you give 20 minutes to, and what got in the way?', 0, true),
  ('5b5add39-54a3-50d5-a694-8d7163f93bd1', 4, 'Day 4 — coming soon', '', '', '[]'::jsonb, 'What did you do today, and what did you notice?', 0, false),
